SELECT c.tenant_id, c.principal_id AS entity_id, c.event_id || '|' || s.event_id AS evidence_ids FROM events c JOIN events s ON s.tenant_id=c.tenant_id AND s.principal_id=c.principal_id AND s.phase=1 AND s.domain='identity' AND s.action='login_success' AND s.ts-c.ts BETWEEN :min_order_gap AND 1200 WHERE c.phase=1 AND c.domain='email' AND c.action='link_clicked' AND c.suspicious=1 AND NOT EXISTS (SELECT 1 FROM events b WHERE b.phase=0 AND b.tenant_id=s.tenant_id AND b.principal_id=s.principal_id AND b.device_id=s.device_id);
